left join lateral (
  select campos.id
  from public.campos
  where lower(trim(campos.potrero)) = lower(trim(v.potrero_canonico))
    and trim(campos.bloque) = trim(v.bloque_canonico)
  order by campos.activo desc, campos.id
  limit 1
) c on true
on conflict (origen_capa, origen_fid) do update
